import * as THREE from 'three';
export const RELAYS=[[0,5,0],[-10,11,-24],[11,7,-47]];
export const EXIT=[0,11,-69];
export function canActivate(origin,direction,target,blocked=false){const d=new THREE.Vector3(...target).sub(origin);return !blocked&&d.length()<15&&d.length()>.1&&d.normalize().dot(direction)>.975}
export function buildSpace({scene,world,RAPIER,barriers,message,objective,score}){
 scene.background=new THREE.Color(0x05091c);scene.fog=new THREE.FogExp2(0x0b1028,.006);
 let seed=90421;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
 const mat=(color,emissive=0,extra={})=>new THREE.MeshStandardMaterial({color,roughness:.72,emissive,emissiveIntensity:.45,...extra});
 const pink=mat(0xd982a0),purple=mat(0x7568ad),stone=mat(0x70667f),pale=mat(0xd9bfd1),cyan=mat(0x73eee7,0x288caa),green=mat(0x8bd09f,0x245d4c);
 function mesh(geometry,material,x,y,z){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);scene.add(m);return m}
 // Invisible volume only: movement is free in every direction, with no ground plane.
 for(const [x,y,z,w,h,d] of [[-29,11,-28,1,26,102],[29,11,-28,1,26,102],[0,-2,-28,58,1,102],[0,25,-28,58,1,102],[0,11,-79,58,26,1],[0,11,23,58,26,1]])world.createCollider(RAPIER.ColliderDesc.cuboid(w/2,h/2,d/2).setTranslation(x,y,z));
 // Dense asteroid field. Large asteroids collide; small ones create depth without taxing physics.
 const asteroids=[],asteroidGeo=new THREE.DodecahedronGeometry(1,1),asteroidMats=[mat(0x6b6278),mat(0x925f6e),mat(0x5a7180)];
 for(let i=0;i<58;i++){let x=(random()-.5)*52,y=1+random()*21,z=18-random()*91;if(Math.abs(x)<5&&z>4){x+=(x<0?-1:1)*8}const r=.45+random()*2.3,a=mesh(asteroidGeo,asteroidMats[i%3],x,y,z),sx=r*(.75+random()*.6),sy=r*(.65+random()*.7),sz=r*(.75+random()*.7);a.scale.set(sx,sy,sz);a.rotation.set(random()*3,random()*3,random()*3);a.userData.spin=(random()-.5)*.22;asteroids.push(a);barriers.push(a);world.createCollider(RAPIER.ColliderDesc.ball(Math.max(sx,sy,sz)).setTranslation(x,y,z))}
 // 3D nebula volumes inspired by the peach, cream and teal reference clouds.
 const nebula=[];for(let i=0;i<38;i++){const side=i%2?-1:1,n=mesh(new THREE.SphereGeometry(2+random()*4,9,7),new THREE.MeshBasicMaterial({color:i%4===0?0x5eaea9:i%3===0?0xf0c6bd:0xd38399,transparent:true,opacity:.07,depthWrite:false}),side*(31+random()*12),8+random()*22,-18-random()*55);n.scale.set(1.5,.8+random(),1);nebula.push(n)}
 // Distant ringed planet and moon; both are real geometry, not a flat backdrop.
 const planet=mesh(new THREE.SphereGeometry(9,32,20),mat(0xb9aacd),30,29,-58);planet.rotation.z=.28;const orbit=mesh(new THREE.TorusGeometry(13,.4,10,90),mat(0xff9b86,0x7b303b),30,29,-58);orbit.rotation.set(1.12,.18,.3);mesh(new THREE.SphereGeometry(5,24,16),mat(0x70aeba),-33,24,-42);
 const stars=new Float32Array(1300*3);for(let i=0;i<stars.length;i+=3){stars[i]=(random()-.5)*190;stars[i+1]=(random()-.25)*100;stars[i+2]=(random()-.75)*180}scene.add(new THREE.Points(new THREE.BufferGeometry().setAttribute('position',new THREE.BufferAttribute(stars,3)),new THREE.PointsMaterial({size:.14,color:0xe3f1ff})));
 // White-and-pink toy spacecraft from the first reference image.
 const mother=new THREE.Group(),hull=new THREE.Mesh(new THREE.SphereGeometry(2.15,24,14),mat(0xf4ece7));hull.scale.set(1,.62,1.35);mother.add(hull);const canopy=new THREE.Mesh(new THREE.SphereGeometry(1.25,20,12),mat(0x263957,0x15264a,{metalness:.35}));canopy.position.y=.72;canopy.scale.set(1,.62,1);mother.add(canopy);for(const side of [-1,1]){const pod=new THREE.Mesh(new THREE.CapsuleGeometry(.45,1.1,5,10),pink);pod.position.set(side*2,-.35,.25);pod.rotation.z=Math.PI/2;mother.add(pod)}for(const x of [-.9,0,.9]){const lamp=new THREE.Mesh(new THREE.SphereGeometry(.2,10,7),x?pink:cyan);lamp.position.set(x,0,-1.9);mother.add(lamp)}mother.position.set(-9,6,14);mother.rotation.y=.35;scene.add(mother);world.createCollider(RAPIER.ColliderDesc.ball(3).setTranslation(-9,6,14));barriers.push(hull);
 // Alien vehicles: glowing saucers with visible green pilots.
 const saucers=[];function makeSaucer(x,y,z,accent,phase){const g=new THREE.Group(),disc=new THREE.Mesh(new THREE.CylinderGeometry(1.7,.9,.38,24),mat(accent,accent));g.add(disc);const dome=new THREE.Mesh(new THREE.SphereGeometry(.85,16,9,0,Math.PI*2,0,Math.PI/2),new THREE.MeshPhysicalMaterial({color:0x9bdbdc,transparent:true,opacity:.42,roughness:.1,depthWrite:false}));dome.position.y=.18;g.add(dome);const pilot=new THREE.Mesh(new THREE.SphereGeometry(.34,12,8),green);pilot.position.y=.48;pilot.scale.y=1.25;g.add(pilot);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.35,.09,7,32),mat(0x82fff0,0x34c8bd));ring.rotation.x=Math.PI/2;ring.position.y=-.15;g.add(ring);g.position.set(x,y,z);scene.add(g);const rb=world.createRigidBody(RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(x,y,z));world.createCollider(RAPIER.ColliderDesc.ball(1.75),rb);barriers.push(g);saucers.push({g,base:new THREE.Vector3(x,y,z),phase,ring,rb});return g}makeSaucer(9,13,-9,0xe77caa,0);makeSaucer(-13,7,-34,0x75d7bd,2);makeSaucer(12,16,-59,0xf29a72,4);
 // Friendly-looking 3D space monsters guard the route and react to paint shots.
 const monsters=[];function makeMonster(x,y,z,color,phase){const g=new THREE.Group(),body=new THREE.Mesh(new THREE.SphereGeometry(1.05,16,12),mat(color,color));body.scale.set(1,.9,1.15);g.add(body);for(const side of [-1,1]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.25,10,7),mat(0xf6f2e9));eye.position.set(side*.38,.25,-.88);g.add(eye);const pupil=new THREE.Mesh(new THREE.SphereGeometry(.11,8,6),mat(0x19223b));pupil.position.set(side*.38,.25,-1.1);g.add(pupil);const horn=new THREE.Mesh(new THREE.ConeGeometry(.16,.75,8),pink);horn.position.set(side*.55,.9,0);horn.rotation.z=side*-.35;g.add(horn)}for(let i=0;i<5;i++){const tentacle=new THREE.Mesh(new THREE.CapsuleGeometry(.09,.65,4,7),purple);tentacle.position.set((i-2)*.3,-.95,.1);tentacle.rotation.z=(i-2)*.13;g.add(tentacle)}g.position.set(x,y,z);scene.add(g);const rb=world.createRigidBody(RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(x,y,z));world.createCollider(RAPIER.ColliderDesc.ball(1.4),rb);barriers.push(g);monsters.push({g,body,base:new THREE.Vector3(x,y,z),phase,hp:2,friendly:false,color,rb});return g}makeMonster(-5,8,-8,0x78c89a,1);makeMonster(7,14,-31,0xd27eb3,3);makeMonster(-7,7,-54,0x79a9dd,5);
 // Floating relay satellites and a distant space gate.
 const relays=RELAYS.map((p,i)=>{world.createCollider(RAPIER.ColliderDesc.ball(.9).setTranslation(...p));world.createCollider(RAPIER.ColliderDesc.cuboid(.13,1.2,.13).setTranslation(p[0],p[1]-1.4,p[2]));const core=mesh(new THREE.OctahedronGeometry(.75),mat(0xffcf8c,0xcf7139),...p),ring=mesh(new THREE.TorusGeometry(1.35,.1,9,40),cyan.clone(),...p);ring.rotation.x=i*.45;const mast=mesh(new THREE.CylinderGeometry(.08,.12,2.4,8),purple,p[0],p[1]-1.4,p[2]);const dish=mesh(new THREE.ConeGeometry(.75,.3,18,1,true),pale,p[0],p[1]-2.5,p[2]);dish.rotation.x=Math.PI;barriers.push(core,mast,dish);return {core,ring,mast,dish,active:false}});
 for(let i=0;i<16;i++){const a=i*Math.PI*2/16;world.createCollider(RAPIER.ColliderDesc.ball(.38).setTranslation(EXIT[0]+Math.cos(a)*2.8,EXIT[1]+Math.sin(a)*2.8,EXIT[2]))}
 const gate=mesh(new THREE.TorusGeometry(2.8,.32,12,48),mat(0x7760a8,0x301a5f),...EXIT),inner=mesh(new THREE.CircleGeometry(2.5,40),new THREE.MeshBasicMaterial({color:0x7866c9,transparent:true,opacity:.12,side:THREE.DoubleSide,depthWrite:false}),...EXIT);inner.rotation.y=Math.PI;const gateRings=[gate];barriers.push(gate);for(let i=1;i<3;i++){const r=mesh(new THREE.TorusGeometry(2.8+i*.45,.08,8,48),cyan.clone(),...EXIT);r.rotation.z=i*.5;gateRings.push(r)}
 let completed=false,checkpoint=new THREE.Vector3(0,3,12),cooldown=0;const shots=[];
 function counts(){return {energy:relays.filter(r=>r.active).length,friends:monsters.filter(m=>m.friendly).length}}
 function updateGoal(){const {energy,friends}=counts();score.textContent=`אנרגיה ${energy}/3 · חברים ${friends}/3`;objective.textContent=completed?'השלב הושלם! שער החלל הופעל':energy===3?'שער החלל פתוח · רחפו אליו בין האסטרואידים':'רחפו בין האסטרואידים והפעילו 3 לווייני אנרגיה';gate.material.color.setHex(energy===3?0xbca1ff:0x7760a8);gate.material.emissive.setHex(energy===3?0x653dcc:0x301a5f)}
 function clearShot(s){scene.remove(s.mesh);s.mesh.geometry.dispose();s.mesh.material.dispose()}
 function fire(origin,direction){if(cooldown>0||completed)return;cooldown=.3;const bolt=mesh(new THREE.SphereGeometry(.13,8,6),cyan.clone(),origin.x,origin.y,origin.z);shots.push({mesh:bolt,direction:direction.clone(),life:1});scene.updateMatrixWorld(true);
  const monsterHits=monsters.filter(m=>!m.friendly).map(m=>({m,d:m.g.position.distanceTo(origin),dot:m.g.position.clone().sub(origin).normalize().dot(direction)})).filter(x=>x.d<16&&x.dot>.972).sort((a,b)=>a.d-b.d);if(monsterHits.length){const {m}=monsterHits[0];m.hp--;m.body.material.emissiveIntensity=1.5;if(m.hp<=0){m.friendly=true;m.body.material.color.setHex(0x7fe5bd);m.body.material.emissive.setHex(0x2d8b75);message('שליו: מפלצת החלל הפכה לחברה שלנו!')}else message('פגיעה בצבע! עוד פגיעה אחת והיא תהפוך לחברה.');updateGoal();return}
  const candidates=relays.filter(r=>!r.active).map(r=>({r,d:r.core.position.distanceTo(origin)})).sort((a,b)=>a.d-b.d);for(const {r,d} of candidates){const ray=new THREE.Raycaster(origin,r.core.position.clone().sub(origin).normalize(),0,d-.8),blocked=ray.intersectObjects(barriers,true).length>0;if(canActivate(origin,direction,r.core.position.toArray(),blocked)){r.active=true;r.core.material.color.setHex(0x75ffe2);r.core.material.emissive.setHex(0x238b75);checkpoint.copy(r.core.position).add(new THREE.Vector3(0,0,2));updateGoal();message(relays.every(r=>r.active)?'שליו: שער החלל נפתח! רחף אליו דרך שדה האסטרואידים.':'שליו: הלוויין חזר לפעול! חפש את הלוויין הזהוב הבא.');return}}message('כוון את סימן ＋ אל מפלצת חלל או אל לוויין זהוב והתקרב.');
 }
 function step(p){if(!completed&&relays.every(r=>r.active)&&new THREE.Vector3(p.x,p.y,p.z).distanceTo(gate.position)<2.4){completed=true;updateGoal();message('שליו: עברנו את שדה האסטרואידים! שלב החלל הראשון הושלם.');document.querySelector('#win').hidden=false}}
 function animate(dt,time){cooldown=Math.max(0,cooldown-dt);asteroids.forEach(a=>{a.rotation.y+=a.userData.spin*dt;a.rotation.x+=a.userData.spin*dt*.35});nebula.forEach((n,i)=>{n.material.opacity=.055+Math.sin(time*.18+i)*.018});planet.rotation.y=time*.025;orbit.rotation.z=time*.018;saucers.forEach((s,i)=>{s.g.position.set(s.base.x+Math.sin(time*.35+s.phase)*2,s.base.y+Math.sin(time*.6+s.phase)*1.2,s.base.z+Math.cos(time*.3+s.phase)*1.5);s.g.rotation.y=time*.35+s.phase;s.rb.setNextKinematicTranslation({x:s.g.position.x,y:s.g.position.y,z:s.g.position.z});s.ring.material.emissiveIntensity=.8+Math.sin(time*3+i)*.35});monsters.forEach((m,i)=>{m.g.position.set(m.base.x+Math.sin(time*.55+m.phase)*1.2,m.base.y+Math.sin(time*.9+m.phase)*.7,m.base.z+Math.cos(time*.5+m.phase)*.8);m.g.rotation.y=Math.sin(time*.5+m.phase)*.35;m.rb.setNextKinematicTranslation({x:m.g.position.x,y:m.g.position.y,z:m.g.position.z});m.body.material.emissiveIntensity=THREE.MathUtils.lerp(m.body.material.emissiveIntensity,m.friendly?.45:.2,.05)});relays.forEach((r,i)=>{r.core.rotation.y=time*.7;r.ring.rotation.z=time*.25+i;r.ring.material.emissiveIntensity=r.active?.15:.8+Math.sin(time*2+i)*.3});gateRings.forEach((r,i)=>r.rotation.z+=(i?-.18:.1)*dt);inner.material.opacity=relays.every(r=>r.active)?.3+.1*Math.sin(time*3):.08;for(let i=shots.length-1;i>=0;i--){const s=shots[i];s.mesh.position.addScaledVector(s.direction,25*dt);s.life-=dt;if(s.life<=0){clearShot(s);shots.splice(i,1)}}}
 function reset(){relays.forEach(r=>{r.active=false;r.core.material.color.setHex(0xffcf8c);r.core.material.emissive.setHex(0xcf7139)});monsters.forEach(m=>{m.friendly=false;m.hp=2;m.body.material.color.setHex(m.color);m.body.material.emissive.setHex(m.color);m.body.material.emissiveIntensity=.2});completed=false;checkpoint.set(0,3,12);document.querySelector('#win').hidden=true;updateGoal()}
 function help(p){const next=relays.find(r=>!r.active);message(next?`שליו: הלוויין הזהוב הבא נמצא ${next.core.position.y>p.y+.8?'מעליך — החזק ↑ כדי לעלות':'עמוק יותר בשדה האסטרואידים'}. כוון אליו ולחץ על כדור הצבע.`:'שליו: כל הלוויינים פעילים! חפש את שער הטבעות הסגול בקצה השדה.');}
 updateGoal();return {fire,step,animate,reset,help,checkpoint,monsters,saucers,asteroids};
}
